-- Verification
-- ============================================================
SELECT count(*) AS saudi_arabia_oil_fields
FROM public.commodity_locations
WHERE country = 'Saudi Arabia' AND commodity_name = 'Crude Oil';

SELECT count(*) AS total_locations
FROM public.commodity_locations;
